import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  texture,
  mix,
  vec3,
  color,
  fract,
  sin,
  dot,
  vec2,
  length,
  smoothstep,
  uniform,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, BoxGeometry, PlaneGeometry, DirectionalLight, Texture, SRGBColorSpace } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'features-card-3';

  const wrapper = new Group();
  root.add(wrapper);

  // ---------------------------------------------------------------------
  // Card body — extruded box (bevel-ish depth) carrying brushed-metal PBR
  // ---------------------------------------------------------------------
  const CARD_W = 1.9;
  const CARD_H = 2.3;
  const CARD_D = 0.07;

  const cardGeo = new BoxGeometry(CARD_W, CARD_H, CARD_D, 1, 1, 1);

  const mapTex = new Texture();
  mapTex.colorSpace = SRGBColorSpace;
  mapTex.needsUpdate = true;

  const inkColor = color(colors.ink);
  const surfaceColor = color(colors.surface);

  const gradientTint = mix(vec3(0.92, 0.93, 0.95), vec3(0.5, 0.51, 0.55), uv().y);
  const texSample = texture(mapTex, uv());
  const grainNoise = fract(
    sin(dot(uv().mul(650.0), vec2(12.9898, 78.233))).mul(43758.5453)
  )
    .sub(0.5)
    .mul(0.028);

  const cardMat = new MeshStandardNodeMaterial();
  cardMat.metalness = 0.5;
  cardMat.roughness = 0.55;
  cardMat.clearcoat = 0.2;
  cardMat.clearcoatRoughness = 0.3;
  cardMat.colorNode = texSample.mul(gradientTint).add(grainNoise);

  const cardMesh = new Mesh(cardGeo, cardMat);
  wrapper.add(cardMesh);

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    mapTex.image = tex.image;
    mapTex.wrapS = tex.wrapS;
    mapTex.wrapT = tex.wrapT;
    mapTex.colorSpace = SRGBColorSpace;
    mapTex.needsUpdate = true;
  }).catch(() => {});

  // ---------------------------------------------------------------------
  // Signal accent stripe — thin emissive line, <=10% of card face
  // ---------------------------------------------------------------------
  const stripeGeo = new PlaneGeometry(CARD_W * 0.72, 0.045);
  const stripeMat = new MeshStandardNodeMaterial();
  stripeMat.metalness = 0.1;
  stripeMat.roughness = 0.6;
  stripeMat.colorNode = color(colors.accent);
  stripeMat.emissiveNode = color(colors.accent).mul(1.4);
  const stripeMesh = new Mesh(stripeGeo, stripeMat);
  stripeMesh.position.set(0, -CARD_H * 0.5 + 0.28, CARD_D * 0.5 + 0.005);
  wrapper.add(stripeMesh);

  // ---------------------------------------------------------------------
  // Contact shadow — radial falloff plane beneath card
  // ---------------------------------------------------------------------
  const shadowRadius = CARD_H * 0.7;
  const shadowGeo = new PlaneGeometry(shadowRadius * 2.2, shadowRadius * 1.4);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  const centeredUv = uv().sub(vec2(0.5, 0.5));
  const dist = length(centeredUv.mul(vec2(1.0, 1.4)));
  const falloff = smoothstep(0.5, 0.0, dist);
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = falloff.mul(0.5);
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -CARD_H * 0.5 - 0.42, -0.02);
  wrapper.add(shadowMesh);

  // ---------------------------------------------------------------------
  // Node-local rim light (accent-tinted), intensity capped <=1.5
  // ---------------------------------------------------------------------
  const rimLight = new DirectionalLight(colors.accent, 0.75);
  rimLight.position.set(-1.2, 0.6, 1.8);
  wrapper.add(rimLight);

  // ---------------------------------------------------------------------
  // Apply any configured cinematic primitives (none specified for this node)
  // ---------------------------------------------------------------------
  const primitiveHandles = [];
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    const applyFn = ctx.primitives?.[prim.name];
    if (applyFn) {
      const handle = applyFn(wrapper, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---------------------------------------------------------------------
  // Motion: weighted-settle entrance + subtle idle breathing (<=2%)
  // ---------------------------------------------------------------------
  wrapper.position.y = 0.3;
  wrapper.scale.setScalar(0.98);
  const opacityUniform = { value: 1 };

  const tl = gsap.timeline();
  tl.to(wrapper.position, {
    y: 0,
    duration: 0.9,
    ease: 'power4.out',
  });
  tl.to(
    wrapper.scale,
    {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.9,
      ease: 'power4.out',
    },
    0
  );

  const breathe = gsap.to(wrapper.scale, {
    x: 1.015,
    y: 1.015,
    z: 1.015,
    duration: 3.2,
    ease: 'sine.inOut',
    yoyo: true,
    repeat: -1,
    delay: 0.9,
  });

  // ---------------------------------------------------------------------
  // Event handler surface (static composition — no interactivity)
  // ---------------------------------------------------------------------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    breathe.kill();

    for (const handle of primitiveHandles) {
      handle.cleanup?.();
    }

    cardGeo.dispose();
    cardMat.dispose();
    stripeGeo.dispose();
    stripeMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    mapTex.dispose();

    wrapper.remove(rimLight);
  };

  return root;
}
